#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    int N = 3 * n;
    vector<int> pos(N + 1);
    for (int i = 0; i < N; i++) { int x; cin >> x; pos[x] = i; }
    vector<array<int, 3>> T(n);
    for (auto &t : T) for (int &x : t) cin >> x;
    int k; cin >> k;
    int ti = -1;
    for (int i = 0; i < n; i++) {
        int cap = T[i][0];
        for (int x : T[i]) if (pos[x] < pos[cap]) cap = x;
        if (cap == k) ti = i;
    }
    vector<char> inC(N + 1, 0);
    vector<int> a;
    if (ti >= 0) {
        for (int x : T[ti]) if (x != k) a.push_back(x);
        for (int j = ti + 1; j < n; j++) for (int x : T[j]) inC[x] = 1;
    }
    vector<int> C;
    for (int v = 1; v <= N; v++) if (inC[v]) C.push_back(v);
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int v = 1; v <= N; v++) if (v != k && !inC[v]) pq.push(v);
    int placed = 0;
    vector<int> out;
    while (!pq.empty()) {
        int v = pq.top(); pq.pop();
        out.push_back(v);
        if (ti >= 0 && (v == a[0] || v == a[1]) && ++placed == 2)
            for (int c : C) pq.push(c);
    }
    for (int v : out) cout << v << ' ';
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n, m, k; ll s;
vector<pair<ll, int>> g1, g2;
vector<ll> ma, mb; vector<int> ia, ib;
// j = number of type-1 gadgets bought on the best prefix-minimum days up to d, or -1
int check(int d) {
    ll A = ma[d], B = mb[d]; int c1 = g1.size(), c2 = g2.size();
    int lo = max(0, k - c2), hi = min(k, c1);
    vector<ll> P1(c1 + 1, 0), P2(c2 + 1, 0);
    for (int i = 0; i < c1; i++) P1[i + 1] = P1[i] + g1[i].first * A;
    for (int i = 0; i < c2; i++) P2[i + 1] = P2[i] + g2[i].first * B;
    int bj = -1; ll best = LLONG_MAX;
    for (int j = lo; j <= hi; j++) if (P1[j] + P2[k - j] < best) best = P1[j] + P2[k - j], bj = j;
    return best <= s ? bj : -1;
}
int main() {
    cin >> n >> m >> k >> s;
    vector<ll> a(n + 1), b(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) cin >> b[i];
    ma.assign(n + 1, 0); mb = ma; ia.assign(n + 1, 0); ib = ia;
    ma[1] = a[1]; ia[1] = 1; mb[1] = b[1]; ib[1] = 1;
    for (int i = 2; i <= n; i++) {
        ma[i] = ma[i - 1]; ia[i] = ia[i - 1]; if (a[i] < ma[i]) ma[i] = a[i], ia[i] = i;
        mb[i] = mb[i - 1]; ib[i] = ib[i - 1]; if (b[i] < mb[i]) mb[i] = b[i], ib[i] = i;
    }
    for (int i = 1; i <= m; i++) { int t; ll c; cin >> t >> c; (t == 1 ? g1 : g2).push_back({c, i}); }
    sort(g1.begin(), g1.end()); sort(g2.begin(), g2.end());
    if (check(n) < 0) { cout << -1 << '\n'; return 0; }
    int lo = 1, hi = n;  // feasibility is monotone in the day
    while (lo < hi) { int mid = (lo + hi) / 2; if (check(mid) >= 0) hi = mid; else lo = mid + 1; }
    int j = check(lo);
    cout << lo << '\n';
    for (int i = 0; i < j; i++) cout << g1[i].second << ' ' << ia[lo] << '\n';
    for (int i = 0; i < k - j; i++) cout << g2[i].second << ' ' << ib[lo] << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s, t; cin >> s >> t;
    int n = s.size(), m = t.size();
    string r(s.rbegin(), s.rend());
    // F[i][j] = lcp(t[i..], s[j..]); G[i][j] = lcp(t[i..], rev(s)[j..])
    vector<vector<int>> F(m + 1, vector<int>(n + 1, 0)), G = F;
    for (int i = m - 1; i >= 0; i--)
        for (int j = n - 1; j >= 0; j--) {
            if (t[i] == s[j]) F[i][j] = F[i + 1][j + 1] + 1;
            if (t[i] == r[j]) G[i][j] = G[i + 1][j + 1] + 1;
        }
    vector<pair<int, int>> pieces;
    int i = 0;
    while (i < m) {
        int best = 0, bx = 0, by = 0;
        for (int j = 0; j < n; j++) {
            if (F[i][j] > best) { best = F[i][j]; bx = j + 1; by = j + best; }
            if (G[i][j] > best) { best = G[i][j]; bx = n - j; by = n - j - best + 1; }
        }
        if (best == 0) { cout << -1 << '\n'; return 0; }
        pieces.push_back({bx, by});
        i += best;
    }
    cout << pieces.size() << '\n';
    for (auto [x, y] : pieces) cout << x << ' ' << y << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<int> par, sz;
int f(int x) { while (par[x] != x) x = par[x] = par[par[x]]; return x; }
int main() {
    int n, m; ll k; cin >> n >> m >> k;
    int N = n * m; vector<ll> a(N); for (auto &x : a) cin >> x;
    vector<int> ord(N); iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return a[x] > a[y]; });
    par.resize(N); iota(par.begin(), par.end(), 0); sz.assign(N, 1);
    vector<char> act(N, 0);
    int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    auto nbrs = [&](int c) {
        vector<int> r;
        for (int d = 0; d < 4; d++) { int x = c / m + dr[d], y = c % m + dc[d]; if (x >= 0 && x < n && y >= 0 && y < m) r.push_back(x * m + y); }
        return r; };
    auto unite = [&](int x, int y) { x = f(x); y = f(y); if (x != y) { if (sz[x] < sz[y]) swap(x, y); par[y] = x; sz[x] += sz[y]; } };
    // values high to low; a component of cells with a >= v must hold k/v cells
    int found = -1; ll fv = 0, fc = 0;
    for (int i = 0; i < N && found < 0;) {
        ll v = a[ord[i]]; int j = i;
        for (; j < N && a[ord[j]] == v; j++) { act[ord[j]] = 1; for (int nb : nbrs(ord[j])) if (act[nb]) unite(ord[j], nb); }
        if (k % v == 0)
            for (int t = i; t < j && found < 0; t++) if (sz[f(ord[t])] >= k / v) found = ord[t], fv = v, fc = k / v;
        i = j;
    }
    if (found < 0) { cout << "NO\n"; return 0; }
    vector<char> inS(N, 0), vis(N, 0); vector<int> q{found}; vis[found] = 1;
    for (size_t h = 0; h < q.size() && (ll)h < fc; h++) {  // first fc BFS cells form a connected set
        int c = q[h]; inS[c] = 1;
        for (int nb : nbrs(c)) if (act[nb] && !vis[nb]) vis[nb] = 1, q.push_back(nb);
    }
    cout << "YES\n";
    for (int r = 0; r < n; r++) for (int c = 0; c < m; c++) cout << (inS[r * m + c] ? fv : 0) << (c + 1 < m ? ' ' : '\n');
}

