#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    ll n, k; cin >> n >> k;
    vector<ll> c(n); ll S = 0;
    for (auto &x : c) { cin >> x; S += x; }
    ll loCap = S / n, hiCap = (S + n - 1) / n;
    // largest x <= floor(avg) with sum of raises <= k
    ll lo = 0, hi = loCap;
    while (lo < hi) {
        ll mid = (lo + hi + 1) / 2, cost = 0;
        for (ll v : c) if (v < mid) cost += mid - v;
        if (cost <= k) lo = mid; else hi = mid - 1;
    }
    ll mn = lo;
    // smallest y >= ceil(avg) with sum of cuts <= k
    lo = hiCap; hi = *max_element(c.begin(), c.end());
    while (lo < hi) {
        ll mid = (lo + hi) / 2, cost = 0;
        for (ll v : c) if (v > mid) cost += v - mid;
        if (cost <= k) hi = mid; else lo = mid + 1;
    }
    cout << lo - mn << '\n';
}

#include <bits/stdc++.h>
using namespace std;
struct E { int to, cap; };
vector<E> es; vector<vector<int>> g; vector<int> lv, it;
void add(int u, int v, int c) { g[u].push_back(es.size()); es.push_back({v, c}); g[v].push_back(es.size()); es.push_back({u, 0}); }
bool bfs(int s, int t) {
    lv.assign(g.size(), -1); queue<int> q; q.push(s); lv[s] = 0;
    while (!q.empty()) { int u = q.front(); q.pop(); for (int id : g[u]) if (es[id].cap > 0 && lv[es[id].to] < 0) lv[es[id].to] = lv[u] + 1, q.push(es[id].to); }
    return lv[t] >= 0;
}
int dfs(int u, int t, int f) {
    if (u == t) return f;
    for (int &i = it[u]; i < (int)g[u].size(); i++) {
        int id = g[u][i], v = es[id].to;
        if (es[id].cap > 0 && lv[v] == lv[u] + 1) {
            int d = dfs(v, t, min(f, es[id].cap));
            if (d > 0) { es[id].cap -= d; es[id ^ 1].cap += d; return d; }
        }
    }
    return 0;
}
int main() {
    int n, m, k, l; cin >> n >> m >> k;
    vector<int> A(k); for (int &x : A) cin >> x;
    cin >> l; vector<int> B(l); for (int &x : B) cin >> x;
    int N = n * m; sort(A.begin(), A.end()); sort(B.begin(), B.end());
    int S = 0, T = 1, base = 2, pa = base + N, pb = pa + k; g.assign(pb + l, {});
    for (int j = 0; j < k; j++) { add(pa + j, T, 1); if (j + 1 < k) add(pa + j, pa + j + 1, N); }
    for (int j = 0; j < l; j++) { add(pb + j, T, 1); if (j + 1 < l) add(pb + j, pb + j + 1, N); }
    for (int y = 1, id = 0; y <= m; y++) for (int x = 1; x <= n; x++) {
        int v = base + id++; add(S, v, 1);
        int ia = lower_bound(A.begin(), A.end(), x + y) - A.begin();
        if (ia < k) add(v, pa + ia, 1);
        int ib = lower_bound(B.begin(), B.end(), x + (m + 1 - y)) - B.begin();
        if (ib < l) add(v, pb + ib, 1);
    }
    int flow = 0;  // every seat must get one person: feasible iff max flow == n*m
    while (bfs(S, T)) { it.assign(g.size(), 0); while (int f = dfs(S, T, INT_MAX)) flow += f; }
    cout << (flow == N ? "YES" : "NO") << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, p, s; cin >> n >> p >> s;
    vector<long long> a(n), b(n);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;
    vector<int> ord(n); iota(ord.begin(), ord.end(), 0);
    // exchange argument: among the chosen p+s students, the top p by a-b are programmers
    sort(ord.begin(), ord.end(), [&](int x, int y) { return a[x] - b[x] > a[y] - b[y]; });
    int T = p + s;
    const long long NEG = LLONG_MIN / 4;
    vector<long long> dp(T + 1, NEG); dp[0] = 0;
    vector<vector<char>> take(n, vector<char>(T + 1, 0));
    for (int idx = 0; idx < n; idx++) {
        int i = ord[idx];
        for (int c = min(idx + 1, T); c >= 1; c--) {
            if (dp[c - 1] == NEG) continue;
            long long v = dp[c - 1] + (c <= p ? a[i] : b[i]);
            if (v > dp[c]) { dp[c] = v; take[idx][c] = 1; }
        }
    }
    vector<int> prog, sp;
    int c = T;
    for (int idx = n - 1; idx >= 0 && c > 0; idx--)
        if (take[idx][c]) {
            int i = ord[idx];
            if (c <= p) prog.push_back(i + 1); else sp.push_back(i + 1);
            c--;
        }
    cout << dp[T] << '\n';
    for (int x : prog) cout << x << ' ';
    cout << '\n';
    for (int x : sp) cout << x << ' ';
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n; cin >> n;
    vector<string> nm(n); vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> nm[i] >> a[i];
    int m; cin >> m;
    vector<ll> P(n, 0);
    for (int i = 0; i < m; i++) cin >> P[i];
    string vn; cin >> vn;
    int vi = find(nm.begin(), nm.end(), vn) - nm.begin();
    sort(P.begin(), P.end());  // ascending, zeros padded
    // best place: Vasya takes the largest points; maximise others who stay behind him
    ll V = a[vi] + P[n - 1];
    vector<ll> rem(P.begin(), P.begin() + n - 1), thr;
    for (int j = 0; j < n; j++) if (j != vi)
        thr.push_back(V - a[j] - (nm[j] > vn ? 0 : 1));
    sort(thr.begin(), thr.end());
    size_t p = 0; int match = 0;
    for (ll t : thr) if (p < rem.size() && rem[p] <= t) { p++; match++; }
    int best = 1 + (n - 1 - match);
    // worst place: Vasya takes the smallest points; maximise others who get ahead of him
    ll W = a[vi] + P[0];
    vector<ll> rem2(P.begin() + 1, P.end()), need;
    for (int j = 0; j < n; j++) if (j != vi)
        need.push_back(W - a[j] + (nm[j] < vn ? 0 : 1));
    sort(need.begin(), need.end());
    size_t i = 0; int mt = 0;
    for (ll x : rem2) if (i < need.size() && x >= need[i]) { i++; mt++; }
    cout << best << ' ' << 1 + mt << '\n';
}

