int main() {
    long long nn; string k; cin >> nn >> k;
    int m = k.size();
    const L CAP = (L)1000000000000000000LL;  // answer <= 1e18, larger prefixes can be dropped
    vector<L> dp(m + 1, -1); dp[0] = 0;
    for (int i = 0; i < m; i++) {
        if (dp[i] < 0) continue;
        L v = 0;
        for (int j = i; j < m; j++) {
            if (j > i && k[i] == '0') break;   // no leading zeros inside a digit
            v = v * 10 + (k[j] - '0');
            if (v >= nn) break;                // digit value must be < base
            L cand = dp[i] * nn + v;
            if (cand > CAP) continue;
            if (dp[j + 1] < 0 || cand < dp[j + 1]) dp[j + 1] = cand;
        }
    }
    cout << (long long)dp[m] << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct S { ll tot, pre, suf, best; };
S mk(const vector<ll> &v) {
    S s{0, LLONG_MIN, LLONG_MIN, LLONG_MIN};
    ll cur = LLONG_MIN;
    for (ll x : v) {
        s.tot += x;
        s.pre = max(s.pre, s.tot);
        cur = (cur == LLONG_MIN) ? x : max(x, cur + x);
        s.best = max(s.best, cur);
    }
    ll acc = 0;
    for (int i = (int)v.size() - 1; i >= 0; i--) { acc += v[i]; s.suf = max(s.suf, acc); }
    return s;
}
S mg(const S &a, const S &b) {
    S r;
    r.tot = a.tot + b.tot;
    r.pre = max(a.pre, a.tot + b.pre);
    r.suf = max(b.suf, b.tot + a.suf);
    r.best = max({a.best, b.best, a.suf + b.pre});
    return r;
}
int main() {
    int n, m; cin >> n >> m;
    vector<S> arr(n);
    for (int i = 0; i < n; i++) {
        int l; cin >> l;
        vector<ll> v(l); for (ll &x : v) cin >> x;
        arr[i] = mk(v);
    }
    int id; cin >> id;
    S res = arr[id - 1];
    for (int i = 1; i < m; i++) { cin >> id; res = mg(res, arr[id - 1]); }
    cout << res.best << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n;
vector<vector<int>> g;
vector<ll> L, X, Y, dep;
int DX[4] = {1, 0, -1, 0}, DY[4] = {0, 1, 0, -1};
// back = direction from v to its parent; children avoid it
void dfs(int v, int p, int back, ll x, ll y) {
    X[v] = x; Y[v] = y;
    int used = back >= 0 ? (1 << back) : 0;
    for (int c : g[v]) if (c != p) {
        int d = 0; while ((used >> d) & 1) d++;
        used |= 1 << d;
        ll len = L[dep[c]];
        dfs(c, v, (d + 2) % 4, x + DX[d] * len, y + DY[d] * len);
    }
}
int main() {
    cin >> n; g.assign(n, {});
    for (int i = 0; i < n - 1; i++) { int u, v; cin >> u >> v; u--; v--; g[u].push_back(v); g[v].push_back(u); }
    for (auto &a : g) if (a.size() > 4) { puts("NO"); return 0; }
    dep.assign(n, 0); vector<int> q{0}; vector<char> vis(n, 0); vis[0] = 1; int H = 0;
    for (size_t h = 0; h < q.size(); h++) {
        int v = q[h];
        for (int c : g[v]) if (!vis[c]) { vis[c] = 1; dep[c] = dep[v] + 1; H = max<int>(H, dep[c]); q.push_back(c); }
    }
    // edge length at depth d: 2*(extent below) + 1, so sibling subtrees never meet
    L.assign(H + 2, 0); vector<ll> G(H + 2, 0);
    for (int d = H; d >= 1; d--) { L[d] = 2 * G[d + 1] + 1; G[d] = G[d + 1] + L[d]; }
    X.assign(n, 0); Y.assign(n, 0);
    dfs(0, -1, -1, 0, 0);
    puts("YES");
    for (int i = 0; i < n; i++) printf("%lld %lld\n", X[i], Y[i]);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n; scanf("%d", &n);
    vector<int> p(n + 1), tin(n + 1), sz(n + 1, 1), ord, st;
    vector<ll> t(n + 1), sub(n + 1, 0);
    vector<vector<int>> ch(n + 1);
    int root = 0;
    for (int i = 1; i <= n; i++) {
        scanf("%d %lld", &p[i], &t[i]);
        if (p[i]) ch[p[i]].push_back(i); else root = i;
    }
    st.push_back(root);
    while (!st.empty()) {  // preorder: every subtree is contiguous
        int v = st.back(); st.pop_back();
        tin[v] = ord.size(); ord.push_back(v);
        for (int c : ch[v]) st.push_back(c);
    }
    for (int i = n - 1; i >= 0; i--) {
        int v = ord[i]; sub[v] += t[v];
        if (p[v]) sub[p[v]] += sub[v], sz[p[v]] += sz[v];
    }
    ll S = sub[root];
    if (((S % 3) + 3) % 3) { puts("-1"); return 0; }
    ll T = S / 3;
    vector<int> TL, TT;
    for (int v : ord) if (v != root && sub[v] == T) TL.push_back(v), TT.push_back(tin[v]);
    for (size_t i = 0; i + 1 < TL.size(); i++) {  // two consecutive unrelated subtrees, each worth T
        int u = TL[i], v = TL[i + 1];
        if (tin[v] >= tin[u] + sz[u]) { printf("%d %d\n", u, v); return 0; }
    }
    for (int u : ord) {  // subtree worth 2T with a strict descendant worth T
        if (u == root || sub[u] != 2 * T) continue;
        size_t idx = upper_bound(TT.begin(), TT.end(), tin[u]) - TT.begin();
        if (idx < TT.size() && TT[idx] < tin[u] + sz[u]) { printf("%d %d\n", u, TL[idx]); return 0; }
    }
    puts("-1");
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// max points for a problem given s solvers out of N participants
ll X(ll s, ll N) {
    if (32 * s <= N) return 3000;
    if (16 * s <= N) return 2500;
    if (8 * s <= N) return 2000;
    if (4 * s <= N) return 1500;
    if (2 * s <= N) return 1000;
    return 500;
}
int main() {
    int n; cin >> n;
    vector<array<int, 5>> a(n);
    vector<ll> sj(5, 0);
    for (auto &r : a) for (int j = 0; j < 5; j++) { cin >> r[j]; if (r[j] != -1) sj[j]++; }
    // fake accounts never change Petya's relative standing except through x, and each
    // problem is independent: pick the better of "no fake solvers" or "all fakes solve".
    for (ll f = 0; f <= 6000; f++) {
        ll N = n + f, diff = 0;
        for (int j = 0; j < 5; j++) {
            ll vt = a[0][j], pt = a[1][j];
            auto contrib = [&](ll x) {
                ll d = 0;
                if (vt != -1) d += x * (250 - vt);
                if (pt != -1) d -= x * (250 - pt);
                return d;
            };
            ll best = contrib(X(sj[j], N));
            if (vt != -1) best = max(best, contrib(X(sj[j] + f, N)));
            diff += best;
        }
        if (diff > 0) { cout << f << '\n'; return 0; }
    }
    cout << -1 << '\n';
}

