using namespace std;
typedef long long ll;
int main() {
    int n; cin >> n;
    vector<ll> x(n), y(n), r(n);
    for (int i = 0; i < n; i++) cin >> x[i] >> y[i] >> r[i];
    // circles form a laminar family; the odd-covered area of a half is the signed sum
    // of areas with sign (-1)^(number of same-half ancestors). The best split gives
    // +area to depth 0 and odd depth, -area to even depth >= 2 (verified by brute force).
    ll K = 0;
    for (int i = 0; i < n; i++) {
        int d = 0;
        for (int j = 0; j < n; j++) if (j != i && r[j] > r[i]) {
            ll dx = x[i] - x[j], dy = y[i] - y[j], q = r[j] - r[i];
            if (dx * dx + dy * dy <= q * q) d++;
        }
        ll sq = r[i] * r[i];
        K += (d == 0 || d % 2 == 1) ? sq : -sq;
    }
    printf("%.10Lf\n", (long double)K * acosl(-1.0L));
}

