#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; cin >> n >> k;
    vector<int> p(k); for (int &x : p) cin >> x;
    set<int> unused; for (int v = 1; v <= n; v++) unused.insert(v);
    vector<int> st, out;
    int cur = 1;  // smallest value not yet output
    auto settle = [&]() { while (!st.empty() && st.back() == cur) { st.pop_back(); cur++; } };
    for (int v : p) {
        if (!st.empty() && v > st.back()) { puts("-1"); return 0; }
        st.push_back(v); unused.erase(v); out.push_back(v);
        settle();
    }
    while ((int)out.size() < n) {
        int v;
        if (st.empty()) v = *unused.rbegin();
        else {
            auto it = unused.lower_bound(st.back());
            if (it == unused.begin()) { puts("-1"); return 0; }
            v = *prev(it);  // largest free value below the stack top
        }
        unused.erase(v); st.push_back(v); out.push_back(v);
        settle();
    }
    for (int i = 0; i < n; i++) cout << out[i] << (i + 1 < n ? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll n; ll K;
// minimal number of terms 2^e (e <= M) summing to n
ll f(int M) {
    if (M >= 0) return (n >> M) + __builtin_popcountll(n & ((1LL << M) - 1));
    if (n > K || -M > 20) return LLONG_MAX / 2;
    return n << (-M);
}
int main() {
    int k; cin >> n >> k; K = k;
    int M = -20;
    while (M <= 60 && f(M) > K) M++;
    if (M > 60) { puts("No"); return 0; }
    map<ll, ll> cnt;  // exponent -> how many terms
    if (M >= 0) {
        if (n >> M) cnt[M] = n >> M;
        for (int i = 0; i < M; i++) if ((n >> i) & 1) cnt[i]++;
    } else cnt[M] = n << (-M);
    ll total = f(M);
    while (total < K) {  // split the smallest term: keeps the largest terms intact
        auto it = cnt.begin(); ll e = it->first;
        if (--it->second == 0) cnt.erase(it);
        cnt[e - 1] += 2; total++;
    }
    puts("Yes");
    bool first = true;
    for (auto it = cnt.rbegin(); it != cnt.rend(); ++it)
        for (ll c = 0; c < it->second; c++) { cout << (first ? "" : " ") << it->first; first = false; }
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// fill the larger side greedily by cheapest |t-T| per unit of flow, within budget
double fill(vector<pair<ll, ll>> &v, ll budget) {
    sort(v.begin(), v.end());
    double f = 0;
    for (auto [d, a] : v) {
        if (budget <= 0) break;
        if (a * d <= budget) { f += a; budget -= a * d; }
        else { f += (double)budget / d; budget = 0; }
    }
    return f;
}
int main() {
    int n; ll T; cin >> n >> T;
    vector<ll> a(n), t(n);
    for (auto &x : a) cin >> x;
    for (auto &x : t) cin >> x;
    double ans = 0;
    vector<pair<ll, ll>> hot, cold;  // (|t-T|, a)
    ll P = 0, N = 0, sumHot = 0, sumCold = 0;
    for (int i = 0; i < n; i++) {
        if (t[i] == T) ans += a[i];
        else if (t[i] > T) { hot.push_back({t[i] - T, a[i]}); P += a[i] * (t[i] - T); sumHot += a[i]; }
        else { cold.push_back({T - t[i], a[i]}); N += a[i] * (T - t[i]); sumCold += a[i]; }
    }
    // the smaller side is used in full; the larger side is limited by that side's total heat budget
    if (P >= N) { ans += sumCold + fill(hot, N); }
    else        { ans += sumHot + fill(cold, P); }
    cout << setprecision(15) << fixed << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n; ll r, k;
vector<ll> a, pre;
// can every section reach defense level M with at most k extra archers?
bool ok(ll M) {
    vector<ll> ends(n + 2, 0);
    ll cur = 0, cost = 0;
    for (int i = 0; i < n; i++) {
        cur -= ends[i];
        ll base = pre[min<ll>(n, i + r + 1)] - pre[max<ll>(0, i - r)];
        ll def = base + cur;
        if (def < M) {
            ll need = M - def;
            cost += need;
            if (cost > k) return false;
            cur += need;
            // place the archers as far right as useful: section p = min(i+r, n-1)
            ll p = min<ll>(n - 1, i + r);
            ends[min<ll>(n, p + r + 1)] += need;
        }
    }
    return true;
}
int main() {
    cin >> n >> r >> k;
    a.resize(n); for (auto &x : a) cin >> x;
    pre.assign(n + 1, 0);
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
    ll lo = 0, hi = 2000000000000000000LL;
    while (lo < hi) {
        ll mid = lo + (hi - lo + 1) / 2;
        if (ok(mid)) lo = mid; else hi = mid - 1;
    }
    cout << lo << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<int> p(n + 1); int root = 1;
    vector<vector<int>> ch(n + 1);
    for (int i = 1; i <= n; i++) { cin >> p[i]; if (p[i] == 0) root = i; else ch[p[i]].push_back(i); }
    if (n % 2 == 0) { cout << "NO\n"; return 0; }  // n-1 edges must split into even counts
    // subtree sizes via BFS order
    vector<int> order{root};
    for (size_t h = 0; h < order.size(); h++) for (int c : ch[order[h]]) order.push_back(c);
    vector<int> sz(n + 1, 1);
    for (int i = n - 1; i >= 0; i--) if (p[order[i]]) sz[p[order[i]]] += sz[order[i]];
    // emit(v): even-size children first (they remove the edge to v), then v, then odd children
    vector<int> out;
    vector<pair<int, int>> st{{0, root}};  // (0 = emit subtree, 1 = output node)
    while (!st.empty()) {
        auto [t, v] = st.back(); st.pop_back();
        if (t == 1) { out.push_back(v); continue; }
        for (int c : ch[v]) if (sz[c] % 2 == 1) st.push_back({0, c});
        st.push_back({1, v});
        for (int c : ch[v]) if (sz[c] % 2 == 0) st.push_back({0, c});
    }
    cout << "YES\n";
    for (int v : out) cout << v << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int n, m, s;
vector<vector<int>> g;
vector<int> idx, low, comp, stk;
vector<char> on;
int timer_ = 0, nc = 0;
void dfs(int v) {  // Tarjan SCC
    idx[v] = low[v] = ++timer_;
    stk.push_back(v); on[v] = 1;
    for (int w : g[v]) {
        if (!idx[w]) { dfs(w); low[v] = min(low[v], low[w]); }
        else if (on[w]) low[v] = min(low[v], idx[w]);
    }
    if (low[v] == idx[v]) {
        while (true) {
            int w = stk.back(); stk.pop_back();
            on[w] = 0; comp[w] = nc;
            if (w == v) break;
        }
        nc++;
    }
}
int main() {
    cin >> n >> m >> s;
    g.assign(n + 1, {});
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; g[u].push_back(v); }
    idx.assign(n + 1, 0); low = idx; comp = idx; on.assign(n + 1, 0);
    for (int v = 1; v <= n; v++) if (!idx[v]) dfs(v);
    vector<int> indeg(nc, 0);
    for (int u = 1; u <= n; u++)
        for (int v : g[u]) if (comp[u] != comp[v]) indeg[comp[v]]++;
    // every source SCC other than the capital's must receive one new road
    int ans = 0;
    for (int c = 0; c < nc; c++) if (indeg[c] == 0 && c != comp[s]) ans++;
    cout << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; cin >> n >> k;
    vector<string> g(n); for (auto &s : g) cin >> s;
    const int INF = 1e9;
    vector<vector<int>> d(n, vector<int>(n, INF));
    // d[i][j] = fewest non-'a' cells on a right/down path from (0,0) to (i,j)
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
        int c = g[i][j] != 'a';
        if (i == 0 && j == 0) d[i][j] = c;
        else d[i][j] = min(i > 0 ? d[i - 1][j] : INF, j > 0 ? d[i][j - 1] : INF) + c;
    }
    int L = -1;  // furthest diagonal reachable with all 'a' (after <= k changes)
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if (d[i][j] <= k) L = max(L, i + j);
    vector<vector<char>> fr(n, vector<char>(n, 0));  // frontier on current diagonal
    string res; int diag;
    if (L < 0) { res += g[0][0]; fr[0][0] = 1; diag = 0; }
    else {
        res.assign(L + 1, 'a'); diag = L;
        for (int i = 0; i < n; i++) { int j = L - i; if (j >= 0 && j < n && d[i][j] <= k) fr[i][j] = 1; }
    }
    vector<char> cand(n);
    for (int s = diag + 1; s <= 2 * n - 2; s++) {
        char mn = 'z' + 1;
        for (int i = max(0, s - (n - 1)); i <= min(n - 1, s); i++) {
            int j = s - i;
            cand[i] = (i > 0 && fr[i - 1][j]) || (j > 0 && fr[i][j - 1]);
            if (cand[i]) mn = min<char>(mn, g[i][j]);
        }
        for (int i = max(0, s - (n - 1)); i <= min(n - 1, s); i++) {
            int j = s - i;
            fr[i][j] = cand[i] && g[i][j] == mn;
        }
        res += mn;
    }
    cout << res << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, m; scanf("%d %d", &n, &m);
    vector<ll> x(n), y(n);
    for (int i = 0; i < n; i++) scanf("%lld %lld", &x[i], &y[i]);
    // pair (i,j) costs min(x_i+y_j, x_j+y_i); the smaller one is x_i+y_j iff x_i-y_i <= x_j-y_j
    vector<int> ord(n); iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int a, int b) { return x[a] - y[a] < x[b] - y[b]; });
    vector<ll> px(n + 1, 0), py(n + 1, 0);
    for (int p = 0; p < n; p++) { px[p + 1] = px[p] + x[ord[p]]; py[p + 1] = py[p] + y[ord[p]]; }
    vector<ll> tot(n, 0);
    for (int p = 0; p < n; p++) {
        int i = ord[p];
        // later positions j: x_i + y_j ; earlier positions j: x_j + y_i
        tot[i] = (ll)(n - 1 - p) * x[i] + (py[n] - py[p + 1]) + (ll)p * y[i] + px[p];
    }
    for (int e = 0; e < m; e++) {
        int u, v; scanf("%d %d", &u, &v); u--; v--;
        ll c = min(x[u] + y[v], x[v] + y[u]);
        tot[u] -= c; tot[v] -= c;
    }
    for (int i = 0; i < n; i++) printf("%lld%c", tot[i], i + 1 < n ? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, k; scanf("%d %d", &n, &k);
    int M = (1 << k) - 1;
    vector<int> p(n + 1, 0);
    for (int i = 1; i <= n; i++) { int a; scanf("%d", &a); p[i] = p[i - 1] ^ a; }
    // prefix xor q_j can be p_j or p_j ^ M (complement flips the suffix); q_0 = 0 is fixed.
    // Equal prefixes form pairs with xor 0. Group by the class {v, v^M}.
    map<int, ll> cnt;
    for (int i = 1; i <= n; i++) cnt[min(p[i], p[i] ^ M)]++;
    ll eq = 0;
    for (auto [key, t] : cnt) {
        ll best = LLONG_MAX;
        if (key == 0) {  // value 0 also holds the fixed q_0
            for (ll x = 0; x <= t; x++) best = min(best, (x + 1) * x / 2 + (t - x) * (t - x - 1) / 2);
        } else {
            for (ll x = 0; x <= t; x++) best = min(best, x * (x - 1) / 2 + (t - x) * (t - x - 1) / 2);
        }
        eq += best;
    }
    ll N1 = n + 1;
    printf("%lld\n", N1 * (N1 - 1) / 2 - eq);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n; scanf("%d", &n);
    int h = n / 2;
    vector<ll> x(h);
    for (auto &v : x) scanf("%lld", &v);
    ll R = 0;  // previous prefix sum is R^2; take the smallest feasible next root
    vector<ll> out;
    for (int i = 0; i < h; i++) {
        ll X = x[i], bestA = -1, bestB = LLONG_MAX;
        // X = (b-a)(b+a) with d=b-a < e=b+a, same parity
        for (ll d = 1; d * d < X; d++) if (X % d == 0) {
            ll e = X / d;
            if (d < e && (d + e) % 2 == 0) {
                ll a = (e - d) / 2, b = (e + d) / 2;
                if (a > R && b < bestB) { bestB = b; bestA = a; }
            }
        }
        if (bestA < 0) { puts("No"); return 0; }
        out.push_back(bestA * bestA - R * R);
        out.push_back(X);
        R = bestB;
    }
    puts("Yes");
    for (size_t i = 0; i < out.size(); i++) printf("%lld%c", out[i], i + 1 < out.size() ? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int m, k, n, s; scanf("%d %d %d %d", &m, &k, &n, &s);
    vector<int> a(m + 2);
    for (int i = 1; i <= m; i++) scanf("%d", &a[i]);
    const int V = 500001;
    vector<int> need(V + 1, 0), cnt(V + 1, 0);
    int D = 0;
    for (int i = 0; i < s; i++) { int b; scanf("%d", &b); if (need[b]++ == 0) D++; }
    // for each start l, the smallest r with [l..r] containing the schematic (two pointers)
    int sat = 0, r = 0, L = -1, R = -1;
    for (int l = 1; l <= m; l++) {
        while (r < m && sat < D) { r++; int t = a[r]; if (++cnt[t] == need[t]) sat++; }
        if (sat < D) break;
        int RR = max(r, l + k - 1);  // window must hold at least k flowers
        if (RR <= m && (long long)(l - 1) / k + 1 + (m - RR) / k >= n) { L = l; R = RR; break; }
        int t = a[l]; if (need[t] && cnt[t] == need[t]) sat--; cnt[t]--;
    }
    if (L < 0) { puts("-1"); return 0; }
    vector<int> rem;
    for (int i = 1; i <= (L - 1) % k; i++) rem.push_back(i);  // align prefix to multiple of k
    int toRemove = (R - L + 1) - k;
    vector<char> keep(R - L + 1, 0);
    vector<int> rn = need;
    for (int p = L; p <= R; p++) if (rn[a[p]] > 0) { rn[a[p]]--; keep[p - L] = 1; }
    for (int p = L; p <= R && toRemove > 0; p++) if (!keep[p - L]) { rem.push_back(p); toRemove--; }
    printf("%d\n", (int)rem.size());
    for (size_t i = 0; i < rem.size(); i++) printf("%d%c", rem[i], i + 1 < rem.size() ? ' ' : '\n');
    if (rem.empty()) puts("");
}
